KiB, MiB = 1024, 1024 * 1024

def round_size(size):
    if size < 512:
        return 512
    return 512 * ceil(size / 512)

def pick_pool(rounded):
    return "small" if rounded <= 1 * MiB else "large"

def new_segment_size(rounded):  # only on a pool miss
    if rounded <= 1 * MiB:
        return 2 * MiB
    if rounded < 10 * MiB:
        return 20 * MiB   # large_segment_size_mb default
    return 2 * MiB * ceil(rounded / (2 * MiB))

for size in [4, 1048577, 3145728, 25000000]:
    r = round_size(size)
    print(size, r, pick_pool(r), new_segment_size(r))

